namespace {using U=std::uint32_t;constexpr U sites[]={0x10001250,0x100012a0,0x100057b0,0x10005780,0x10001990,0x100018d0,0x10003730,0x100034a0,0x100035f0,0x10003680};constexpr U sizes[]={4,4,4,4,4,0x18,4,8,4,12};
struct Test{std::array<U,24>row{};std::vector<std::uint8_t>data=std::vector<std::uint8_t>(0x100000),stack=std::vector<std::uint8_t>(0x100000);dfre::MissionNetsockPacketMemoryBindings foreign;std::unique_ptr<dfre::MissionNetsockPacketMemory>image;struct F{U site,at,n,id;};std::vector<F>frames;U serial=0,reads=0,writes=0,calls=0,sleeps=0,frees=0,callbacks=0,polls=0;std::uint64_t trace=0;
Test(const dfre::AssetBytes&raw){auto&f=foreign;f.read=[&](U a,U n){U v=0;for(U i=0;i<n;++i)v|=U(*ptr(a+i,1))<<(8*i);return v;};f.write=[&](U a,U n,U v){for(U i=0;i<n;++i)*ptr(a+i,1)=std::uint8_t(v>>(8*i));};f.resolve=[&](U a,std::size_t n){return ptr(a,n);};image=std::make_unique<dfre::MissionNetsockPacketMemory>(raw,f);}
std::uint8_t*ptr(U a,std::size_t n){if(a>=0x1200000&&std::uint64_t(a-0x1200000)+n<=data.size())return data.data()+a-0x1200000;if(a>=0x3000000&&std::uint64_t(a-0x3000000)+n<=stack.size())return stack.data()+a-0x3000000;throw std::runtime_error("Close fixture address is not mapped");}U get(U a,U n=4){return image->read(a,n);}void put(U a,U v,U n=4){image->write(a,n,v);}U norm(U a){for(auto i=frames.rbegin();i!=frames.rend();++i)if(a>=i->at&&a<i->at+i->n)return 0x30000000+i->id*0x1000+a-i->at;return a;}void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}bool mapped(U a,U n){if(a>=0x10000000&&std::uint64_t(a)+n<=0x1001b000)return true;if(a>=0x1200000&&std::uint64_t(a)+n<=0x1300000)return true;for(auto f:frames)if(a>=f.at&&std::uint64_t(a)+n<=std::uint64_t(f.at)+f.n)return true;return false;}U frame(U s){for(auto i=frames.rbegin();i!=frames.rend();++i)if(i->site==s)return i->at;return 0;}U make(U s,U n,const std::vector<U>&args){const U a=0x3000000+serial*0x400;frames.push_back({s,a,n,serial++});std::fill_n(ptr(a,n),n,0x5a);U off=s==0x100052e0?0x34:s==0x10005020?0x24:4;for(U v:args){put(a+off,v);off+=4;}return a;}
void setup(){serial=reads=writes=calls=sleeps=frees=callbacks=polls=0;trace=1469598103934665603ull;frames.clear();std::fill(data.begin(),data.end(),0x5a);std::fill_n(image->resolve(0x10019880,0x426),0x426,0);for(auto[a,v]:std::vector<std::pair<U,U>>{{0x10019880,row[1]},{0x10019884,row[2]},{0x100198ac,row[5]},{0x100199b8,row[6]},{0x100199bc,row[7]},{0x10019c9e,row[8]},{0x10019860,row[9]},{0x100199dc,0x1240000},{0x10019c5c,0x1220000},{0x10019c60,0x1228000},{0x10019c64,0x10000},{0x10019854,0x1260000},{0x1001985c,0x10000},{0x100096b4,55},{0x100096b0,66},{0x100096a8,77},{0x100096ac,88},{0x100198a8,0x0200007f},{0x1000604c,0x1100100},{0x10006010,0x1100200},{0x10006048,0x1100300},{0x10006068,0x1100400},{0x10006000,0x1100500},{0x100199c0,0x1100600},{0x100199c4,99}})put(a,v);put(0x10019868,0xf123,2);for(U j=0;j<4;++j){put(0x12000e0+j*4,0x11111111u*(j+1));put(0x100199cc+j*4,0x11111111u*(j+1));}std::fill_n(ptr(0x1240000,0x8000),0x8000,0);for(U i=0;i<32;++i)put(0x1240000+i*0x10e +0x106,i<row[14]?1:0);}
dfre::MissionNetsockCloseBindings bindings(){dfre::MissionNetsockCloseBindings b;b.read=[&](U a,U n){event(1);event(norm(a));event(n);if(++reads==row[17]||!mapped(a,n))throw std::runtime_error("Read failure");if((row[15]&4)&&a==0x100199c4)put(0x100199c0,0x1100800);if((row[15]&32)&&a==0x100199cc)put(0x100199d0,0xabcdef01);return get(a,n);};b.write=[&](U a,U n,U v){event(2);event(norm(a));event(n);event(norm(n==4?v:v&((1u<<(8*n))-1)));if(++writes==row[18]||!mapped(a,n))throw std::runtime_error("Store failure");if((row[15]&2)&&a==0x10019860){put(0x100096b0,67);put(0x10006000,0x1100900);}if((row[15]&256)&&a==0x100199bc)put(0x100199dc,0x1244000);put(a,v,n);};b.before_call=[&](U s,const auto&args){event(3);event(s);event(U(args.size()));for(U v:args)event(norm(v));if(++calls==row[19])throw std::runtime_error("Call failure");if((row[15]&128)&&s==0x100014c0&&frame(0x100018d0)){U f=frame(0x100018d0);put(f+4,0x1201000);put(f+12,0x1100800);put(f+16,0xdead1234);put(f+20,0xdead5678);put(0x12000e0,0xdeadbeef);}if((row[15]&16)&&s==0x10005020){put(0x10019c5c,0x1224000);put(0x1220002,0x18,2);put(0x10019868,0x4567,2);if(frame(0x100034a0))put(frame(0x100034a0)+4,0x0300007f);}bool own=false;for(U q:sites)if(q==s)own=true;const bool leaf=(row[16]&2)&&(s==0x10005020||s==0x10005830||s==0x10005934||s==0x1000592e||s==0x10005952);if(!own&&!leaf&&s!=0x100014c0&&s!=0x1100100&&s!=0x1100200&&s!=0x1100300&&s!=0x1100400&&s!=0x1100500&&s!=0x1100600&&s!=0x1100700&&s!=0x1100800&&s!=0x1100900&&s!=0x1000596a&&s!=0x10005964&&s!=0x10005916)throw std::runtime_error("Required foreign body");};b.call=[&](U s,const auto&args)->U{if(s==0x1000596a)return row[10];if(s==0x10005964)return row[11];if(s==0x10005916)return 10038;if(s==0x1100100)return 123;if(s==0x1100200){++sleeps;if(row[15]&64)put(0x10006010,0x1100900);if(args.at(0)==10){if(sleeps>=row[13])put(0x100199b8,0);}else if(sleeps>=row[13])put(0x100199bc,1);return 0;}if(s==0x1100300)return 0;if(s==0x1100400||s==0x1100700){if(++frees==1&&(row[15]&1)){put(0x10006068,0x1100700);put(0x10019c60,0x122c000);put(0x100199dc,0x1244000);}return row[12];}if(s==0x1100500||s==0x1100900)return row[12];if(s==0x1100600||s==0x1100800){if(++callbacks==1&&(row[15]&8)){put(0x100199dc,0x1244000);put(0x100199c4,100);put(0x100199c0,0x1100800);put(0x1240000+31*0x10e +0x106,1);}return 1234;}if(s==0x10005934){put(args.at(2),++polls==1?row[20]:0);return 0;}if(s==0x1000592e)return((args.at(0)&255)<<8)|((args[0]>>8)&255);if(s==0x10005952)return args.at(2);throw std::runtime_error("Close required import is not bound");};b.frame=[&](U s,U n,const auto&args){return make(s,n,args);};b.release=[&](U,U,U){frames.pop_back();};b.resolve=[&](U a,std::size_t n){return image->resolve(a,n);};return b;}
};}
int main(int argc,char**argv){if(argc!=2)return 1;std::ifstream file(argv[1],std::ios::binary);dfre::AssetBytes raw((std::istreambuf_iterator<char>(file)),{});Test t(raw);std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);for(U&v:t.row)if(!(in>>v))return 2;t.setup();auto b=t.bindings();const U op=t.row[0];std::vector<U>args;if(op==5)args={t.row[3]?0x1200000u:0u,0xaabbccdd,t.row[4]?0x1100600u:0u,99,0x77777777};if(op==7)args={0x0200007f};const U f=t.make(sites[op],sizes[op],args);bool failed=false;U result=0;try{result=dfre::mission_netsock_close_call(b,sites[op],f);}catch(const std::runtime_error&){failed=true;}if(t.frames.size()!=1)return 3;std::uint64_t state=1469598103934665603ull;for(auto[a,n]:std::vector<std::pair<U,U>>{{0x10019880,0x426},{0x100096a8,16},{0x10006000,0x80},{0x1200000,0x2000},{0x1220000,0x10000},{0x1240000,0x8000},{0x1260000,0x10000}}){const auto*p=t.image->resolve(a,n);for(U i=0;i<n;++i){state^=p[i];state*=1099511628211ull;}}if(failed)result=0;std::cout<<failed<<' '<<result<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<state<<'\n';}}
